<script setup>import{auditLabel,subjectLabel}from'../../../config/auditEvents';import AuditEventBadge from './AuditEventBadge.vue';defineProps({event:Object});defineEmits(['close']);const date=v=>v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'Not recorded';const display=v=>v===null||v===undefined?'Not recorded':typeof v==='object'?JSON.stringify(v):String(v)</script><template><div v-if="event" class="fixed inset-0 z-50 bg-slate-950/30" @click.self="$emit('close')"><aside class="audit-drawer"><header class="flex items-center justify-between border-b p-6"><h2 class="text-xl font-bold">Audit Event Details</h2><button class="menu-trigger" aria-label="Close audit details" @click="$emit('close')">&times;</button></header><div class="space-y-6 overflow-y-auto p-6"><div><AuditEventBadge :event="event.action"/><h3 class="mt-3 text-xl font-bold">{{auditLabel(event.action)}}</h3><p class="mt-1 text-sm text-slate-500">{{event.description||'No description recorded.'}}</p></div><dl class="detail-list"><div><dt>Date &amp; Time</dt><dd>{{date(event.created_at)}}</dd></div><div><dt>Actor</dt><dd>{{event.actor_name||'System'}}</dd></div><div><dt>Actor Email</dt><dd>{{event.actor_email||'Not recorded'}}</dd></div><div><dt>Module</dt><dd>{{event.module||'System'}}</dd></div><div><dt>Target</dt><dd>{{event.subject_name||subjectLabel(event.subject_type)}} · ID #{{event.subject_id}}</dd></div><div><dt>Clinic / Tenant</dt><dd>{{event.tenant_name||'Platform'}}</dd></div><div><dt>IP Address</dt><dd>{{event.ip_address||'Not recorded'}}</dd></div><div><dt>User Agent</dt><dd class="break-all">{{event.user_agent||'Not recorded'}}</dd></div><div><dt>Request</dt><dd>{{event.request_method||'Not recorded'}} · {{event.request_url||'Not recorded'}}</dd></div><div><dt>Raw Event Key</dt><dd><code>{{event.action}}</code></dd></div></dl><section v-if="Object.keys(event.old_values||{}).length"><h3 class="font-bold">Changes</h3><div class="table-wrap mt-3"><table><thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody><tr v-for="(before,key) in event.old_values" :key="key"><td class="font-semibold">{{key.replaceAll('_',' ')}}</td><td>{{display(before)}}</td><td class="text-teal-700">{{display(event.new_values?.[key])}}</td></tr></tbody></table></div></section><details class="rounded-xl border p-4"><summary class="cursor-pointer font-semibold">Raw Event Data (JSON)</summary><pre class="mt-4 overflow-auto whitespace-pre-wrap text-xs">{{JSON.stringify(event,null,2)}}</pre></details></div></aside></div></template>
